put('com/seedsbits/game/preview/AuditHarness.java','''package com.seedsbits.game.preview;
import com.getcapacitor.*;import com.yandex.mobile.ads.common.*;import com.yandex.mobile.ads.rewarded.*;import com.yandex.mobile.ads.interstitial.*;import com.yandex.mobile.ads.banner.*;import android.content.res.Configuration;import android.os.*;
public class AuditHarness {
 static SeedsMonetizationPlugin fresh(boolean ready){Handler.tasks.clear();BannerAdView.all.clear();SeedsMonetizationPlugin p=new SeedsMonetizationPlugin();p.load();if(ready)YandexAds.ready();return p;}
 static PluginCall request(String k){return new PluginCall(new JSObject().put("kind",k).put("attempt","native-audit"));}
 static PluginCall box(){return new PluginCall(new JSObject().put("visible",true).put("viewportWidth",390).put("x",16).put("y",750).put("width",358).put("height",72));}
 static void check(String name,boolean pass,String detail){System.out.printf("%s|%s|%s%n",name,pass,detail);}
 public static void main(String[]x){
  SeedsMonetizationPlugin p=fresh(true);RewardedAd a=new RewardedAd();RewardedAdLoader.last.listener.onAdLoaded(a);p.show(request("rewarded"));a.listener.onAdShown();a.listener.onRewarded(new Reward());String first=(String)p.events.get(0).get("token");p.acknowledge(new PluginCall(new JSObject().put("token",first)));a.listener.onRewarded(new Reward());check("N01_duplicate_reward_after_ack",p.events.size()==1,"native receipts="+p.events.size());
  p=fresh(false);p.banner(box());YandexAds.ready();check("N02_delayed_sdk_banner",BannerAdView.all.size()>0,"banner requests after SDK ready="+BannerAdView.all.size());
  p=fresh(true);p.banner(box());BannerAdView old=BannerAdView.all.get(0);BannerAdEventListener late=old.listener;p.handleOnConfigurationChanged(new Configuration());p.banner(box());BannerAdView next=BannerAdView.all.get(1);late.onAdFailedToLoad(new AdRequestError());check("N03_stale_banner_callback",!next.destroyed,"replacement destroyed="+next.destroyed);
  p=fresh(true);a=new RewardedAd();RewardedAdLoader.last.listener.onAdLoaded(a);PluginCall pending=request("rewarded");p.show(pending);Handler.fire();check("N04_missing_preshow_callback",pending.result!=null,"deadline released call="+(pending.result!=null));
  p=fresh(true);int count=RewardedAdLoader.last.requests;RewardedAdLoader.last.listener.onAdFailedToLoad(new AdRequestError());p.preload(new PluginCall());check("N05_no_immediate_retry",RewardedAdLoader.last.requests==count,"requests="+RewardedAdLoader.last.requests);SystemClock.now+=60001;p.preload(new PluginCall());check("N06_retry_after_interval",RewardedAdLoader.last.requests==count+1,"requests="+RewardedAdLoader.last.requests);
  p=fresh(true);InterstitialAd i=new InterstitialAd();InterstitialAdLoader.last.listener.onAdLoaded(i);PluginCall recent=request("interstitial");p.show(recent);check("N07_initial_grace",i.shows==0,"shows="+i.shows);p.activity.prefs.edit().putLong("last_fullscreen",System.currentTimeMillis()-181000).commit();p.show(request("interstitial"));check("N08_interval_eligible",i.shows==1,"shows="+i.shows);i.listener.onAdShown();i.listener.onAdDismissed();InterstitialAd nextI=new InterstitialAd();InterstitialAdLoader.last.listener.onAdLoaded(nextI);p.show(request("interstitial"));check("N09_interval_persisted",nextI.shows==0,"shows="+nextI.shows);
  p=fresh(true);a=new RewardedAd();RewardedAdLoader.last.listener.onAdLoaded(a);pending=request("rewarded");p.show(pending);p.handleOnDestroy();check("N10_destroy_unblocks",pending.result!=null,"resolved="+(pending.result!=null));
  p=fresh(true);a=new RewardedAd();RewardedAdLoader.last.listener.onAdLoaded(a);p.show(request("rewarded"));a.listener.onAdShown();a.listener.onRewarded(new Reward());String token=(String)p.events.get(0).get("token");android.content.SharedPreferences game=p.activity.getSharedPreferences("CapacitorStorage",0);game.fail=true;com.capacitorjs.plugins.preferences.Probe.write(p.activity,"progress","bonus=3");p.acknowledge(new PluginCall(new JSObject().put("token",token)));boolean retained=p.activity.prefs.durable.containsKey("reward_token");check("N11_preferences_apply_failure",retained,"volatileGame="+game.data.containsKey("progress")+",durableGame="+game.durable.containsKey("progress")+",nativePending="+retained);
  p=fresh(true);p.activity.prefs.edit().putLong("last_fullscreen",System.currentTimeMillis()-181000).commit();a=new RewardedAd();RewardedAdLoader.last.listener.onAdLoaded(a);p.show(request("rewarded"));a.listener.onAdShown();a.listener.onAdDismissed();i=new InterstitialAd();InterstitialAdLoader.last.listener.onAdLoaded(i);p.show(request("interstitial"));check("N12_reward_delays_interstitial",i.shows==0,"shows="+i.shows);

 }
}''')
