if r.returncode:print(r.stderr);raise SystemExit(r.returncode)
results=[dict(case=s.split('|')[0],passed=s.split('|')[1]=='true',detail=s.split('|')[2])for s in r.stdout.splitlines()];Path('docs/audit-0.6.0/native-harness.json').write_text(json.dumps({'method':'unmodified production Java source compiled with deterministic SDK/Android doubles','results':results},indent=2));print(json.dumps(results,indent=2))
